// static
bool UnionTraits<::ash::cfm::mojom::WebcamId::DataView, ::ash::cfm::mojom::WebcamIdPtr>::Read(
    ::ash::cfm::mojom::WebcamId::DataView input,
    ::ash::cfm::mojom::WebcamIdPtr* output) {
  using UnionType = ::ash::cfm::mojom::WebcamId;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kDeviceId: {
      std::string result_device_id;
      if (!input.ReadDeviceId(&result_device_id))
        return false;

      *output = UnionType::NewDeviceId(
          std::move(result_device_id));
      break;
    }
    case Tag::kDevPath: {
      std::string result_dev_path;
      if (!input.ReadDevPath(&result_dev_path))
        return false;

      *output = UnionType::NewDevPath(
          std::move(result_dev_path));
      break;
    }
    default:

      return false;
  }
  return true;
}

// static
bool UnionTraits<::ash::cfm::mojom::CtrlType::DataView, ::ash::cfm::mojom::CtrlTypePtr>::Read(
    ::ash::cfm::mojom::CtrlType::DataView input,
    ::ash::cfm::mojom::CtrlTypePtr* output) {
  using UnionType = ::ash::cfm::mojom::CtrlType;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kMappingCtrl: {
      ::ash::cfm::mojom::ControlMappingPtr result_mapping_ctrl;
      if (!input.ReadMappingCtrl(&result_mapping_ctrl))
        return false;

      *output = UnionType::NewMappingCtrl(
          std::move(result_mapping_ctrl));
      break;
    }
    case Tag::kQueryCtrl: {
      ::ash::cfm::mojom::ControlQueryPtr result_query_ctrl;
      if (!input.ReadQueryCtrl(&result_query_ctrl))
        return false;

      *output = UnionType::NewQueryCtrl(
          std::move(result_query_ctrl));
      break;
    }
    default:

      return false;
  }
  return true;
}

