XuCameraAsyncWaiter::XuCameraAsyncWaiter(
    XuCamera* proxy) : proxy_(proxy) {}

XuCameraAsyncWaiter::~XuCameraAsyncWaiter() = default;

void XuCameraAsyncWaiter::GetUnitId(
    WebcamIdPtr id, const std::vector<uint8_t>& guid, uint8_t* out_error_code, uint8_t* out_unit_id) {
  base::RunLoop loop;
  proxy_->GetUnitId(std::move(id),std::move(guid),
      base::BindOnce(
          [](base::RunLoop* loop,
             uint8_t* out_error_code
,
             uint8_t* out_unit_id
,
             uint8_t error_code,
             uint8_t unit_id) {*out_error_code = std::move(error_code);*out_unit_id = std::move(unit_id);
            loop->Quit();
          },
          &loop,
          out_error_code,
          out_unit_id));
  loop.Run();
}



void XuCameraAsyncWaiter::MapCtrl(
    WebcamIdPtr id, ControlMappingPtr mapping_ctrl, uint8_t* out_error_code) {
  base::RunLoop loop;
  proxy_->MapCtrl(std::move(id),std::move(mapping_ctrl),
      base::BindOnce(
          [](base::RunLoop* loop,
             uint8_t* out_error_code
,
             uint8_t error_code) {*out_error_code = std::move(error_code);
            loop->Quit();
          },
          &loop,
          out_error_code));
  loop.Run();
}

uint8_t XuCameraAsyncWaiter::MapCtrl(
    WebcamIdPtr id, ControlMappingPtr mapping_ctrl) {
  uint8_t async_wait_result;
  MapCtrl(std::move(id),std::move(mapping_ctrl),&async_wait_result);
  return async_wait_result;
}

void XuCameraAsyncWaiter::GetCtrl(
    WebcamIdPtr id, CtrlTypePtr ctrl, GetFn fn, uint8_t* out_error_code, std::vector<uint8_t>* out_data) {
  base::RunLoop loop;
  proxy_->GetCtrl(std::move(id),std::move(ctrl),std::move(fn),
      base::BindOnce(
          [](base::RunLoop* loop,
             uint8_t* out_error_code
,
             std::vector<uint8_t>* out_data
,
             uint8_t error_code,
             const std::vector<uint8_t>& data) {*out_error_code = std::move(error_code);*out_data = std::move(data);
            loop->Quit();
          },
          &loop,
          out_error_code,
          out_data));
  loop.Run();
}



void XuCameraAsyncWaiter::SetCtrl(
    WebcamIdPtr id, CtrlTypePtr ctrl, const std::vector<uint8_t>& data, uint8_t* out_error_code) {
  base::RunLoop loop;
  proxy_->SetCtrl(std::move(id),std::move(ctrl),std::move(data),
      base::BindOnce(
          [](base::RunLoop* loop,
             uint8_t* out_error_code
,
             uint8_t error_code) {*out_error_code = std::move(error_code);
            loop->Quit();
          },
          &loop,
          out_error_code));
  loop.Run();
}

uint8_t XuCameraAsyncWaiter::SetCtrl(
    WebcamIdPtr id, CtrlTypePtr ctrl, const std::vector<uint8_t>& data) {
  uint8_t async_wait_result;
  SetCtrl(std::move(id),std::move(ctrl),std::move(data),&async_wait_result);
  return async_wait_result;
}






